#[derive(Debug)]
struct Position { row: usize, column: usize }
fn main() {
    let p = Position { row: 2, column: 4 };
    println!("{:?}", p);
    println!("{:#?}", p);
}

#[derive(Debug, PartialEq, Eq)]
struct Key { section: u32, item: u32 }
fn main() {
    let a = Key { section: 1, item: 2 };
    let b = Key { section: 1, item: 3 };
    println!("{}", a == b);
    let n = f64::NAN;
    println!("{}", n == n);
}

#[derive(Debug, PartialEq, Eq, PartialOrd, Ord)]
struct Rank { priority: u8, sequence: u32 }
fn main() {
    let mut items = vec![
        Rank { priority: 2, sequence: 1 },
        Rank { priority: 1, sequence: 9 },
        Rank { priority: 1, sequence: 3 },
    ];
    items.sort();
    for x in items { println!("{}:{}", x.priority, x.sequence); }
}

#[derive(Clone, Copy)]
struct Point { x: i32, y: i32 }
#[derive(Clone)]
struct Note { text: String }
fn main() {
    let p = Point { x: 1, y: 2 };
    let q = p;
    let a = Note { text: "原文".into() };
    let mut b = a.clone();
    b.text.push_str("副本");
    println!("{} {} | {} | {}", p.x, q.y, a.text, b.text);
}

use std::collections::HashSet;
#[derive(PartialEq, Eq, Hash)]
struct Cell { row: u32, column: u32 }
fn main() {
    let mut visited = HashSet::new();
    visited.insert(Cell { row: 1, column: 2 });
    visited.insert(Cell { row: 1, column: 2 });
    println!("{} {}", visited.len(), visited.contains(&Cell { row: 1, column: 2 }));
}

#[derive(Debug, Default)]
struct Options { enabled: bool, limit: usize, label: String }
fn main() {
    let options = Options { limit: 8, ..Default::default() };
    println!("{} {} '{}'", options.enabled, options.limit, options.label);
}
